// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;
    address constant TARGET = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;

    function setUp() public {
        __Sink __s = new __Sink();
        vm.etch(0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C, address(__s).code);
        c = new B();
    }

    function _test(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint targetBefore = TARGET.balance;
        try c.go{value: amount}() {} catch { return; }
        uint targetAfter = TARGET.balance;
        assertTrue(targetAfter - targetBefore == amount);
    }

    function testFuzz_test(uint256 amount) public {
        _test(amount);
    }

    receive() external payable {}
}

contract __Sink {
    fallback() external payable { require(msg.value == 0); }
    receive() external payable { require(msg.value == 0); }
}
